251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        boolean isNew = owner.isNew();
255	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
256	        // roll it forward to the next business day so it never lands on a weekend. Everything
257	        // derived from the registration date below must use this adjusted value.
258	        LocalDate registrationDate = toBusinessDay(
259	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
260	        owner.setRegistrationDate(registrationDate);
261	        // Whether this owner was accepted into an existing household because the request declared it
262	        // shares one (sharesHousehold). A declared member is deliberately not treated as a suspected
263	        // duplicate below.
264	        boolean declaredHouseholdMember = false;
265	        if (owner.isNew()) {
266	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
267	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
268	            // it automatically. It is part of the owner's identityKey, so it is resolved first.
269	            owner.setHouseholdId(computeHouseholdId(owner));
270	            // The household is keyed on (last name, postcode), so the members are the existing owners
271	            // sharing both with this owner.
272	            List<Owner> householdMembers = findHouseholdMembers(owner);
273	            // Size of the household after this create: the existing members plus this new owner.
274	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
275	            // A second owner in an existing household is the same household and is rejected as a
276	            // household duplicate, UNLESS the request declares (via sharesHousehold) that it genuinely
277	            // shares the household. sharesHousehold only bypasses this block; it no longer creates the
278	            // link, which is now derived from (last name, postcode).
279	            if (!householdMembers.isEmpty()) {
280	                if (!owner.isSharesHousehold()) {
281	                    throw new HouseholdDuplicateException(owner.getHouseholdId());
282	                }
283	                declaredHouseholdMember = true;
284	            }
285	        }
286	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
287	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
288	        // subsumes the former separate telephone, email and household checks.
289	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
290	            throw new DuplicateIdentityException(owner.getIdentityKey());
291	        }
292	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
293	        // postcode while carrying a different telephone. Still created, but flagged as a possible
294	        // duplicate pointing at the matching owner. A declared household member is not a suspected
295	        // duplicate, so it is never flagged.
296	        if (owner.isNew() && !declaredHouseholdMember) {
297	            Owner softMatch = findPossibleDuplicate(owner);
298	            if (softMatch != null) {
299	                owner.setPossibleDuplicate(true);
300	                owner.setPossibleDuplicateOf(softMatch.getId());
301	            }
302	        }
303	        if (owner.isNew()
304	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
305	            throw new CityOwnerLimitExceededException(owner.getCity());
306	        }
307	        if (owner.isNew()
308	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
309	            throw new DailyOwnerLimitExceededException(registrationDate);
310	        }
311	        if (owner.isNew() && owner.getCustomerCode() == null) {
312	            owner.setCustomerCode(generateCustomerCode(owner));
313	        }
314	        if (owner.isNew()) {
315	            owner.setNamesakeCount(countNamesakes(owner));
316	            owner.setBulkSignupWarning(
317	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
318	        }
319	        if (owner.getMembershipNumber() == null) {
320	            owner.setMembershipNumber(generateMembershipNumber(owner));
321	        }
322	        ownerRepository.save(owner);
323	        if (isNew) {
324	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
325	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
326	                owner.getRegistrationDate());
327	        }
328	    }
329	
330	    /**
331	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
332	     * owner. The key consolidates telephone, email and household into one value, so two owners
333	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
334	     * the owner's {@code householdId} has been resolved, so its key is complete.
335	     */
336	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
337	        String identityKey = owner.getIdentityKey();
338	        return ownerRepository.findAll().stream()
339	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
340	    }
341	
342	    /**
343	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
344	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
345	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
346	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
347	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
348	     */
349	    private Owner findPossibleDuplicate(Owner owner) {
350	        String lastName = normalizeHouseholdKey(owner.getLastName());
351	        String postcode = owner.getPostcode();
352	        if (lastName == null || postcode == null || postcode.isBlank()) {
353	            return null;
354	        }
355	        String telephone = owner.getTelephone();
356	        return ownerRepository.findAll().stream()
357	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
358	                && postcode.equals(existing.getPostcode())
359	                && !Objects.equals(telephone, existing.getTelephone()))
360	            .min(Comparator.comparing(Owner::getId))
361	            .orElse(null);
362	    }
363	
364	    /**
365	     * Count the owners that already exist (before this create) sharing the same first name and last
366	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
367	     * unique among the existing owners.
368	     */
369	    private int countNamesakes(Owner owner) {
370	        String firstName = owner.getFirstName();
371	        String lastName = owner.getLastName();
372	        if (firstName == null || lastName == null) {
373	            return 0;
374	        }
375	        return (int) ownerRepository.findAll().stream()
376	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
377	                && lastName.equalsIgnoreCase(existing.getLastName()))
378	            .count();
379	    }
380	
381	    /**
382	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
383	     * last name and its postcode. Last names are compared case-insensitively with collapsed
384	     * whitespace; postcodes are compared exactly. This is the same keying used by
385	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
386	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
387	     * postcode to match on.
388	     */
389	    private List<Owner> findHouseholdMembers(Owner owner) {
390	        String lastName = normalizeHouseholdKey(owner.getLastName());
391	        String postcode = owner.getPostcode();
392	        if (lastName == null || postcode == null || postcode.isBlank()) {
393	            return List.of();
394	        }
395	        return ownerRepository.findAll().stream()
396	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
397	                && postcode.equals(existing.getPostcode()))
398	            .toList();
399	    }
400	
401	    /**
402	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
403	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode}, where the last name
404	     * is normalized case-insensitively with collapsed whitespace (see {@link #normalizeHouseholdKey})
405	     * and the postcode is used exactly as stored. Owners with the same last name and postcode
406	     * therefore share the same {@code householdId} automatically. Returns {@code null} when the owner
407	     * has no last name or postcode, so it does not belong to a shared household.
408	     */
409	    private String computeHouseholdId(Owner owner) {
410	        String lastName = normalizeHouseholdKey(owner.getLastName());
411	        String postcode = owner.getPostcode();
412	        if (lastName == null || postcode == null || postcode.isBlank()) {
413	            return null;
414	        }
415	        byte[] digest;
416	        try {
417	            digest = MessageDigest.getInstance("SHA-256")
418	                .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
419	        } catch (NoSuchAlgorithmException e) {
420	            throw new IllegalStateException("SHA-256 is required but not available", e);
421	        }
422	        StringBuilder hex = new StringBuilder(12);
423	        for (int i = 0; i < 6; i++) {
424	            hex.append(String.format("%02x", digest[i]));
425	        }
426	        return hex.toString();
427	    }
428	
429	    /**
430	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
431	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
432	     */
433	    private String normalizeHouseholdKey(String value) {
434	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
435	    }
436	
437	    /**
438	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
439	     * code resolved from the owner's postcode (falling back to the owner's city, else
440	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
441	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
442	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
443	     * derived from the owner's own attributes.
444	     */
445	    private String generateCustomerCode(Owner owner) {
446	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
447	    }
448	
449	    /**
450	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
451	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
452	     * with the owner's last name.
453	     */
454	    private String customerHash(Owner owner) {
455	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
456	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
457	        byte[] digest;
458	        try {
459	            digest = MessageDigest.getInstance("SHA-256")
460	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
461	        } catch (NoSuchAlgorithmException e) {
462	            throw new IllegalStateException("SHA-256 is required but not available", e);
463	        }
464	        StringBuilder hex = new StringBuilder(16);
465	        for (int i = 0; i < 4; i++) {
466	            hex.append(String.format("%02X", digest[i]));
467	        }
468	        return hex.toString();
469	    }
470	
471	    /**
472	     * Count the owners that already exist (before this create) in the same city as {@code owner},
473	     * compared case-insensitively.
474	     */
475	    private long countOwnersInCity(Owner owner) {
476	        String city = owner.getCity();
477	        return ownerRepository.findAll().stream()
478	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
479	            .count();
480	    }
481	
482	    /**
483	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
484	     * on the given {@code date}. Used to enforce the per-day create cap.
485	     */
486	    private long countOwnersRegisteredOn(LocalDate date) {
487	        return ownerRepository.findAll().stream()
488	            .filter(existing -> date.equals(existing.getRegistrationDate()))
489	            .count();
490	    }
491	
492	    /**
493	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
494	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
495	     * are required to fall on a business day.
496	     */
497	    private LocalDate toBusinessDay(LocalDate date) {
498	        switch (date.getDayOfWeek()) {
499	            case SATURDAY:
500	                return date.plusDays(2);
501	            case SUNDAY:
502	                return date.plusDays(1);
503	            default:
504	                return date;
505	        }
506	    }
507	
508	    /**
509	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
510	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
511	     */
512	    private String generateMembershipNumber(Owner owner) {
513	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
514	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
515	    }
516	
517	    @Override
518	    @Transactional(readOnly = true)
519	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
