535	    private <T> T findEntityById(Supplier<T> supplier) {
536	        try {
537	            return supplier.get();
538	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
539	            // Just ignore not found exceptions for Jdbc/Jpa realization
540	            return null;
541	        }
542	    }
